USE radius;
CREATE TABLE IF NOT EXISTS radcheck (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(64), attribute VARCHAR(32), op VARCHAR(2), value VARCHAR(255), INDEX idx_username (username));
CREATE TABLE IF NOT EXISTS radacct (radacctid BIGINT AUTO_INCREMENT PRIMARY KEY, acctsessionid VARCHAR(64), acctuniqueid VARCHAR(64), username VARCHAR(64), groupname VARCHAR(64), realm VARCHAR(64), nasipaddress VARCHAR(32), nasportid VARCHAR(32), nasporttype VARCHAR(32), acctstarttime DATETIME, acctupdatetime DATETIME, acctstoptime DATETIME, acctsessiontime INT, acctauthentic VARCHAR(32), connectinfo_start VARCHAR(32), connectinfo_stop VARCHAR(32), acctinputoctets BIGINT DEFAULT 0, acctoutputoctets BIGINT DEFAULT 0, calledstationid VARCHAR(32), callingstationid VARCHAR(32), acctterminatecause VARCHAR(32), servicetype VARCHAR(32), framedprotocol VARCHAR(32), framedipaddress VARCHAR(32), acctstartdelay INT, acctstopdelay INT);
CREATE TABLE IF NOT EXISTS radusergroup (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(64), groupname VARCHAR(64), priority INT DEFAULT 1, INDEX idx_username (username));
